package io.github.diodeme.ji.storage.sqlite;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.sql.DriverManager;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

final class SqliteMigrationManagerTest {
    @TempDir java.nio.file.Path directory;

    @Test
    void migratesForwardTransactionallyAfterCreatingVerifiedBackup() throws Exception {
        var database = directory.resolve("host.db");
        try (var connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
            connection.createStatement().execute("CREATE TABLE original(value TEXT NOT NULL)");
            connection.createStatement().execute("INSERT INTO original VALUES ('preserved')");
        }
        var manager = new SqliteMigrationManager(database, "host", List.of(
                new SqliteMigration(1, "baseline", List.of("CREATE TABLE added(id INTEGER PRIMARY KEY)")),
                new SqliteMigration(2, "index", List.of("CREATE INDEX added_id ON added(id)"))));

        SqliteMigrationManager.Result result = manager.migrate();

        assertEquals(2, result.schemaVersion());
        assertTrue(result.backup().isPresent());
        assertTrue(Files.isRegularFile(result.backup().orElseThrow()));
        try (var connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
            assertEquals(2, connection.createStatement().executeQuery("PRAGMA user_version").getInt(1));
            assertEquals("preserved", connection.createStatement().executeQuery("SELECT value FROM original").getString(1));
        }
        try (var connection = DriverManager.getConnection("jdbc:sqlite:" + result.backup().orElseThrow())) {
            assertEquals(0, connection.createStatement().executeQuery("PRAGMA user_version").getInt(1));
            assertFalse(connection.createStatement().executeQuery(
                    "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE name='added')").getBoolean(1));
            assertEquals("ok", connection.createStatement().executeQuery("PRAGMA integrity_check").getString(1));
        }
    }

    @Test
    void failedMigrationRollsBackSchemaVersionAndData() throws Exception {
        var database = directory.resolve("failed.db");
        try (var connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
            connection.createStatement().execute("CREATE TABLE original(value TEXT NOT NULL)");
        }
        var manager = new SqliteMigrationManager(database, "host", List.of(
                new SqliteMigration(1, "broken", List.of(
                        "CREATE TABLE partial(id INTEGER)",
                        "INSERT INTO missing_table VALUES (1)"))));

        assertThrows(SqliteMigrationException.class, manager::migrate);

        try (var connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
            assertEquals(0, connection.createStatement().executeQuery("PRAGMA user_version").getInt(1));
            assertFalse(connection.createStatement().executeQuery(
                    "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE name='partial')").getBoolean(1));
        }
    }

    @Test
    void refusesNewerUnknownSchemaAndNeverRunsDownMigration() throws Exception {
        var database = directory.resolve("future.db");
        try (var connection = DriverManager.getConnection("jdbc:sqlite:" + database)) {
            connection.createStatement().execute("PRAGMA user_version=9");
        }
        var manager = new SqliteMigrationManager(database, "host", List.of(
                new SqliteMigration(1, "baseline", List.of("CREATE TABLE current(id INTEGER)"))));

        SqliteMigrationException failure = assertThrows(SqliteMigrationException.class, manager::migrate);
        assertEquals("storage.schema_too_new", failure.code());
    }
}
